(() => {
 const {M,sum,clamp,m,p,a,sel,yes,refs,bars,out,line,add}=CREDIT_UI;
 const stage='03 · Build and validate models',core=['burden','util','arrears','income'],modes=[['core','Economic core'],['duplicate','Core + redundant proxy'],['noise','Core + random code'],['leak','Core + leakage · invalid diagnostic']],keys=mode=>mode==='core'?core:[...core,mode==='duplicate'?'duplicate':mode==='noise'?'noise':'leak'];
 add({id:'data',name:'Data, targets and observation windows',stage,title:'Choose what was knowable at the decision date.',intro:'Place candidate variables and the default outcome on a timeline. Future information can make an unusable model appear excellent.',chart:'Data timestamps relative to the scoring date (months)',inputs:[a('history','Lookback window',3,36,3,12,'months'),a('horizon','Default observation horizon',6,24,6,12,'months'),a('reportLag','Financial-statement availability lag',0,9,1,3,'months'),yes('future','Include a post-default collections flag')],challenge:'A financial statement describes last quarter but arrives next month. Was it available at today’s decision?',formula:'Eligible feature timestamp ≤ scoring date\nTarget window = (scoring date, scoring date + outcome horizon]',simple:'The model must learn from the information a lender could actually have used. An outcome label belongs after the decision; an input variable must be available before it.',scope:'Timeline uses synthetic timestamps: behavioural history ends at month 0; a statement with accounting date −2 arrives after the selected lag; collection flag is recorded at month +6. Availability is distinct from the period described. No real customer data are loaded or transmitted.',sources:[refs.model,refs.ecl],compute(s){const arrival=-2+s.reportLag,bad=arrival>0||s.future==='yes';return out([['Statement available now?',arrival<=0?'Yes':'No'],['Outcome window',s.horizon+' months'],['Leakage issue',bad?'Reject unavailable feature':'None in selected examples']],['History start','Scoring date','Statement arrival','Outcome end'],[-s.history,0,arrival,s.horizon],[['Payment history','Before / at month 0','Candidate behavioural input'],['Statement arrival','Month '+arrival,arrival<=0?'Available':'Do not backdate availability'],['Collections flag','Month +6',s.future==='yes'?'Leakage: remove from model':'Excluded']],`The target is default within ${s.horizon} months. Historical accounting dates do not override when information actually became available.`);}});
 add({id:'variables',name:'Variable selection workbench',stage,title:'Select variables for evidence, stability and economic sense.',intro:'Choose inputs, fit a logistic model to an earlier synthetic cohort, and evaluate it on a later cohort. Inspect data quality, redundancy and leakage alongside performance.',chart:'Standardised fitted coefficients',inputs:[...M.FEATURES.map(([k,label])=>yes(k,label,core.includes(k)?'yes':'no')),a('ridge','Ridge penalty',.01,.5,.01,.05,'penalty')],challenge:'Add the post-default flag. Why is a near-perfect score a reason to reject that feature?',formula:'Candidate review → availability → missingness → economic rationale → redundancy → temporal validation\nPenalised logistic loss = mean log loss + λ/2 × Σ coefficient²',simple:'A variable should help at the time the model will be used. Predictive strength is one piece of evidence; a duplicate adds little new information, an unstable relationship may fail later, and a future outcome is leakage.',scope:'720 reproducible synthetic records, 480 earlier training and 240 later holdout observations. Train-only mean imputation and standardisation; 240 gradient steps with ridge penalty. Fixed five-bin IV/PSI with 0.5 smoothing. Missingness and redundancy are diagnostics, not universal cutoffs. Leakage may be selected only to demonstrate invalid apparent performance. These estimates are not deployable credit scores.',sources:[refs.model],compute(s){const selected=M.FEATURES.filter(([k])=>s[k]==='yes').map(x=>x[0]),fit=M.model(selected,s.ridge),leak=selected.includes('leak'),v=selected.map((_,i)=>fit.b[i+1]);return {stats:[['Training AUC',fit.trainAuc.toFixed(3)],['Later-cohort AUC',fit.testAuc.toFixed(3)],['Candidate status',leak?'INVALID · target leakage':selected.length?'Requires independent review':'Intercept only']],bars:bars(selected.length?selected.map(k=>M.FEATURES.find(x=>x[0]===k)[1]):['Intercept only'],selected.length?v:[0]),headers:['Variable','Included','Missing','Univariate AUC','IV','PSI','|corr| with burden','Review'],rows:M.FEATURES.map(([k,label,role])=>{const d=M.featureStats(k);return[label,selected.includes(k)?'Yes':'No',p(d.missing),d.auc.toFixed(3),d.iv.toFixed(3),d.psi.toFixed(3),d.redundancy.toFixed(3),k==='leak'?'Reject: observed after default':k==='duplicate'?'Review redundancy with burden':role];}),explanation:leak?'The collections flag is the outcome itself. Even excellent later-cohort AUC is invalid because the feature is unavailable at scoring time. Remove it before judging model suitability.':`${selected.length} features selected. AUC measures ordering, not calibrated PD or fairness. Assess missingness, stability, correlated variables and economic rationale before approving any candidate.`,note:'Larger positive coefficients increase predicted default odds. IV and PSI depend on binning; no automatic regulatory approval threshold is implied.'};}});
 add({id:'woe',name:'Binning, WoE and information value',stage,title:'Bins reveal the risk pattern hidden inside a variable.',intro:'Compare default and non-default distributions across fixed bins, with smoothing for sparse cells.',chart:'Weight of evidence by input bin',inputs:[sel('feature','Candidate variable',M.FEATURES.filter(x=>x[0]!=='leak').map(x=>[x[0],x[1]]),'burden'),a('smoothing','Count added to each cell',.5,5,.5,.5,'observations')],challenge:'What happens when a bin has very few defaults? Why should a large WoE be treated cautiously?',formula:'WoE=ln(non-default distribution / default distribution)\nIV=Σ(non-default share−default share)×WoE',simple:'Binning asks whether different ranges of an input contain different default patterns. Sparse samples can create dramatic apparent separation that does not survive a new cohort.',scope:'Earlier synthetic cohort only; five fixed bins on the [0,1] feature scale. Nulls form a separate missing bin. Smoothing adds the chosen count to each default/non-default cell. This is exploratory univariate evidence; IV does not establish causation, stability or incremental multivariate value.',sources:[refs.model],compute(s){const counts=Array.from({length:6},()=>[0,0]);M.DATA.filter(r=>!r.late).forEach(r=>{const v=r[s.feature],i=v===null?5:Math.min(4,Math.floor(v*5));counts[i][r.y]++;});const ng=sum(counts.map(x=>x[0]+s.smoothing)),nb=sum(counts.map(x=>x[1]+s.smoothing)),rows=counts.map((x,i)=>{const g=(x[0]+s.smoothing)/ng,b=(x[1]+s.smoothing)/nb,w=Math.log(g/b);return {label:i===5?'Missing':`${i/5}–${(i+1)/5}`,g:x[0],b:x[1],w,iv:(g-b)*w};});return {stats:[['Total IV',sum(rows.map(x=>x.iv)).toFixed(3)],['Training observations','480'],['Bins including missing','6']],bars:bars(rows.map(x=>x.label),rows.map(x=>x.w)),headers:['Bin','Non-defaults','Defaults','WoE','IV contribution'],rows:rows.map(x=>[x.label,x.g,x.b,x.w.toFixed(3),x.iv.toFixed(4)]),explanation:'Positive WoE under this convention indicates a bin relatively more common among non-defaults. Try another variable and inspect cell counts before interpreting the strength.'};}});
 add({id:'scorecard',name:'Logistic PD and scorecards',stage,title:'Each input changes the odds, then the link turns odds into PD.',intro:'Apply the economic-core model trained on the synthetic earlier cohort to a hypothetical borrower.',chart:'Contributions to the model log-odds',inputs:[a('burden','Debt burden feature',0,1,.05,.5,'scaled'),a('util','Credit utilisation',0,1,.05,.6,'fraction'),yes('arrears','Prior arrears'),a('income','Income stability feature',0,1,.05,.5,'scaled')],challenge:'Move one variable while keeping the others fixed. Is the change in PD constant at every starting point?',formula:'log odds = intercept + Σ β × standardised feature\nPD = 1/(1+exp(−log odds))',simple:'Logistic coefficients act on odds, not directly on percentage-point PD. The same contribution can have a different probability effect depending on the borrower’s starting risk.',scope:'Uses the fixed synthetic economic-core ridge model (penalty 0.05), with training mean and scale. Arrears is binary; other inputs are arbitrary normalised features, not real underwriting ratios. No external score-to-PD mapping, lending decision or protected-characteristic assessment.',sources:[refs.model],compute(s){const fit=M.model(core,.05),r={...s,arrears:s.arrears==='yes'?1:0},con=core.map((k,i)=>fit.b[i+1]*(r[k]-fit.means[i])/fit.sd[i]),pd=fit.score(r);return out([['Predicted teaching PD',p(pd)],['Log odds',(fit.b[0]+sum(con)).toFixed(3)],['Odds',(pd/(1-pd)).toFixed(3)]],['Intercept',...core],[fit.b[0],...con],core.map((k,i)=>[k,con[i].toFixed(3),'Standardised coefficient contribution']),`The model PD is ${p(pd)} for this synthetic profile. Contributions are in log-odds units, so their sum must pass through the logistic function to become a probability.`);}});
 add({id:'validation',name:'Discrimination and decision thresholds',stage,title:'Ranking borrowers and choosing a cutoff are separate decisions.',intro:'Measure AUC, Brier score and the confusion matrix on the later cohort, then change the screening threshold.',chart:'Later-cohort confusion counts',inputs:[sel('mode','Model feature set',modes,'core'),a('threshold','Flag when predicted PD is at least',5,80,5,20,'%')],challenge:'Raise the threshold. Which errors disappear, and which new errors appear?',formula:'AUC = probability a default receives a higher score than a non-default (ties half)\nBrier = mean(predicted probability − outcome)²',simple:'AUC measures rank ordering across cutoffs. A decision threshold determines who is flagged and trades false alarms against missed defaults. Neither number alone proves that predicted PDs are accurate.',scope:'240 later synthetic records with observable outcomes, no production threshold recommendation. A flagged account is a diagnostic label, not an automated rejection. Leakage model included only as an invalid demonstration. No cross-validation or uncertainty intervals in this applet.',sources:[refs.model],compute(s){const f=M.model(keys(s.mode),.05),v=[0,0,0,0];f.pt.forEach((p,i)=>{const flag=p>=s.threshold/100,y=f.labels[i];v[flag?(y?0:1):(y?2:3)]++;});return out([['AUC',f.testAuc.toFixed(3)],['Brier score',f.brier.toFixed(4)],['Recall',v[0]+v[2]?p(v[0]/(v[0]+v[2])):'N/A']],['True positives','False positives','Missed defaults','True negatives'],v,[['Flag threshold',s.threshold+'%','Changes counts, not model scores'],['Precision',v[0]+v[1]?p(v[0]/(v[0]+v[1])):'N/A','Default share among flagged'],['Validity',s.mode==='leak'?'INVALID: future outcome input':'Review model evidence','Metrics do not establish availability']],s.mode==='leak'?'The apparently strong performance uses the target as a feature. The model is invalid for decision-time use.':'Changing the cutoff leaves AUC unchanged because the ranking stays the same. Examine both error types and their consequences.');}});
 add({id:'calibration',name:'PD calibration and PIT / TTC',stage,title:'A model can rank well and still understate default rates.',intro:'Shift the core model’s log-odds and compare mean predictions with outcomes in the later cohort.',chart:'Predicted versus observed default rates by PD bin (%)',inputs:[a('shift','Log-odds calibration adjustment',-2,2,.1,0,'log odds')],challenge:'Change the calibration intercept. Why does the ranking stay the same?',formula:'Adjusted PD = sigmoid(logit(original PD) + shift)',simple:'Calibration aligns probability levels with observed risk. A monotonic adjustment changes the level without changing borrower order. Point-in-time estimates respond to current conditions; long-run calibration answers a different question.',scope:'Fixed later synthetic cohort, not an IFRS 9 or IRB approved calibration. Five fixed PD bins; empty bins omitted. Adjustment is user chosen, not optimised on the holdout. Real PIT/TTC conversion needs economic conditions, cycle coverage and purpose-specific definitions.',sources:[refs.model,refs.ecl],compute(s){const f=M.model(core,.05),ps=f.pt.map(x=>M.sigmoid(M.logit(x)+s.shift)),bins=M.bins(ps,f.labels).filter(x=>x.n),brier=sum(ps.map((x,i)=>(x-f.labels[i])**2))/ps.length;return {stats:[['Mean predicted PD',p(sum(ps)/ps.length)],['Observed default rate',p(sum(f.labels)/f.labels.length)],['Brier',brier.toFixed(4)]],series:[line('Observed',bins.map(x=>[100*x.p,100*x.observed])),line('Perfect calibration',[[0,0],[100,100]],'#779db0')],xlabel:'Mean predicted PD (%)',headers:['PD bin','Count','Predicted','Observed'],rows:bins.map(x=>[x.range,x.n,p(x.p),p(x.observed)]),explanation:`AUC remains ${M.auc(ps,f.labels).toFixed(3)} under the monotonic intercept shift. Calibration and discrimination are separate validation dimensions.`};}});
 add({id:'drift',name:'Population drift and monitoring',stage,title:'Today’s applicants may differ from the development sample.',intro:'Shift population mass toward higher-risk segments and inspect PSI alongside the implied portfolio PD.',chart:'Development and current segment shares (%)',inputs:[a('shift','Mass moved from low to high risk',0,35,1,10,'percentage points')],challenge:'Does a high PSI tell you whether the model’s risk relationship has broken?',formula:'PSI = Σ(current share − development share) × ln(current share / development share)',simple:'Population drift asks who is arriving. Performance drift asks whether the relationship between inputs and outcomes still works. They can occur together or separately.',scope:'Three synthetic segments with fixed PDs 1%, 5%, 15% and development shares 40%, 40%, 20%. Positive shares throughout the control range, no smoothing required. PSI thresholds such as 0.1 or 0.25 are not universal regulatory rules. This applet does not refit the model.',sources:[refs.model],compute(s){const base=[.4,.4,.2],current=[.4-s.shift/100,.4,.2+s.shift/100],rates=[.01,.05,.15],psi=sum(base.map((x,i)=>(current[i]-x)*Math.log(current[i]/x)));return {stats:[['PSI',psi.toFixed(3)],['Development PD',p(sum(base.map((x,i)=>x*rates[i])))],['Current mix PD',p(sum(current.map((x,i)=>x*rates[i])))]],series:[line('Development',base.map((x,i)=>[i+1,100*x])),line('Current',current.map((x,i)=>[i+1,100*x]),'#b57e3e')],xlabel:'Segment 1 low · 2 medium · 3 high risk',headers:['Segment','Development share','Current share','Assumed PD'],rows:base.map((x,i)=>[['Low','Medium','High'][i],p(x),p(current[i]),p(rates[i])]),explanation:'The portfolio PD changes solely because the customer mix changes. PSI flags distribution change; outcome monitoring is needed to assess calibration and discrimination.'};}});
 add({id:'bias',name:'Selection bias and responsible use',stage,title:'Approved borrowers are not the whole applicant population.',intro:'Apply an approval cutoff to synthetic risk scores and see which outcomes the lender would normally observe.',chart:'Accepted and rejected cohort default rates (%)',inputs:[a('cutoff','Approve if core model PD below',5,60,5,25,'%')],challenge:'Can observed defaults among approved loans establish the default rate of rejected applicants?',formula:'Observed-book default rate = defaults among accepted / accepted count',simple:'Approval policy selects the population whose loan outcomes are observed. Changing the policy changes that sample, so a model fitted only on approved borrowers can be misleading for new applicants.',scope:'The simulator knows all synthetic outcomes; rejected-customer outcomes are displayed only to reveal the selection mechanism. They would not ordinarily be observed for that ungranted loan. No reject-inference method is validated here. Responsible use also requires privacy, lawful inputs, proxy review, explainability and appropriate subgroup assessments.',sources:[refs.model],compute(s){const f=M.model(core,.05),accepted=[],rejected=[];f.pt.forEach((x,i)=>(x<s.cutoff/100?accepted:rejected).push(f.labels[i]));const rate=x=>x.length?sum(x)/x.length:0;return out([['Accepted count',accepted.length+''],['Rejected count',rejected.length+''],['Accepted observed rate',accepted.length?p(rate(accepted)):'N/A']],['Accepted rate','Rejected truth · synthetic'],[100*rate(accepted),100*rate(rejected)],[['Accepted outcomes',accepted.length?'Observed on originated loans':'No selected records','Subject to selection'],['Rejected outcomes',rejected.length?'Known only in this simulation':'No selected records','Do not invent real labels']],`The accepted cohort contains ${accepted.length} records. The rejected truth is visible here because the data are simulated; ordinary lending data cannot justify assigning invented good/bad labels.`);}});
 add({id:'vintages',name:'Vintages, censoring and data quality',stage,title:'A young loan book has not had time to show its full risk.',intro:'Compare the same hazard assumption over different observed seasoning windows.',chart:'Cumulative defaults by months on book (%)',inputs:[a('hazard','Annual conditional default probability',.5,20,.5,4,'%'),a('young','Young cohort observation length',3,24,3,6,'months'),a('mature','Mature cohort observation length',24,60,6,36,'months')],challenge:'Why is comparing raw cumulative default rates unfair when cohorts have different ages?',formula:'Monthly hazard = 1 − (1 − annual PD)^(1/12)\nCumulative PD at m months = 1 − (1 − annual PD)^(m/12)',simple:'Recent originations have shorter exposure to default risk. A lower cumulative default rate can reflect less observation time rather than better underwriting.',scope:'Constant hazard, no censoring events actually simulated. The lesson explains why real estimates need exposure-at-risk, default dates, observation end dates and treatment of repayment or closure. Incomplete workout recoveries similarly bias LGD comparisons.',sources:[refs.ecl,refs.model],compute(s){const f=m=>1-(1-s.hazard/100)**(m/12);return {stats:[['Young cumulative PD',p(f(s.young))],['Mature cumulative PD',p(f(s.mature))],['Same assumed annual PD',s.hazard+'%']],series:[line('Cumulative PD',Array.from({length:61},(_,i)=>[i,100*f(i)]))],xlabel:'Months on book',headers:['Cohort','Observed months','Cumulative PD'],rows:[['Young',s.young,p(f(s.young))],['Mature',s.mature,p(f(s.mature))]],explanation:'Both cohorts have the same underlying hazard. Differences in observed maturity alone create different cumulative default rates. Compare like-for-like seasoning before drawing a performance conclusion.'};}});
 const selection=CREDIT_LESSONS.find(l=>l.id==='variables');selection.notes=[
 ['1 · Define the target, population and intended use','Specify default definition, prediction horizon, scoring date and portfolio. Application, behavioural, collections, IFRS 9 and regulatory models can require different data and calibration. Form the candidate list from economic reasoning and available data before looking at outcomes.'],
 ['2 · Establish eligibility and data quality','Check availability timestamps, lawful and intended use, lineage, missingness, outliers and representative coverage. Identify repeated borrowers and related facilities so information cannot leak between development and validation samples. Exclude post-outcome features before assessing predictive strength.'],
 ['3 · Screen and transform candidates','Review univariate patterns, sensible direction, sparse categories and stability through time. Consider bins, missing indicators, monotonicity and transformations. Avoid treating a single IV, significance or PSI threshold as an approval rule. Save transformations fitted only on development data.'],
 ['4 · Test incremental information','Compare correlated variables, redundancy and coefficient stability in multivariable candidates. Use regularisation and a simpler challenger. A feature that looks strong alone may add little after other variables are included; coefficient instability can be a sign of collinearity.'],
 ['5 · Validate on untouched data','Use an appropriate time split and borrower grouping, with cross-validation inside development where suitable. Assess ranking, calibration, sampling uncertainty, subgroup performance and stability in stress. Repeatedly choosing features from the final holdout turns it into development data; reserve genuinely independent evidence.'],
 ['6 · Approve, document and monitor','Document rationale for retained and rejected candidates, limitations, explainability and proxy risks. Obtain appropriate independent validation and approval. Monitor data drift, outcomes and changes in policy or population, with triggers for recalibration, redevelopment or restricted use.']
 ];
})();
